/** Кейсы ПРАЙМ: категории + детальные карточки */

export type CaseCategoryId = "seo" | "ads" | "web" | "bots";

export type CaseCategory = {
  id: CaseCategoryId;
  slug: CaseCategoryId;
  title: string;
  short: string;
  lead: string;
  accent: string;
};

/** Сложное → простыми словами */
export type CasePlainSpeak = {
  jargon: string;
  plain: string;
};

export type CaseStudy = {
  slug: string;
  category: CaseCategoryId;
  title: string;
  client: string;
  industry: string;
  location: string;
  period: string;
  metric: string;
  metricLabel: string;
  summary: string;
  cover: string;
  coverAlt: string;
  services: string[];
  challenge: string;
  approach: string[];
  results: { label: string; value: string }[];
  quote?: { text: string; author: string; role: string };
  featured?: boolean;
  /** Развёрнутый кейс: история клиента */
  intro?: string;
  siteUrl?: string;
  /** С какой болью пришли — развёрнутый заход */
  painLead?: string;
  /** Скрин / фото «до» */
  before?: { src: string; alt: string; caption?: string };
  pains?: { title: string; text: string }[];
  /** Как мы провели клиента — короткий лид к шагам */
  journeyLead?: string;
  /** Сложные вещи простым языком */
  plainSpeak?: CasePlainSpeak[];
  /** Шаги работы: текст + экран (половина на половину) */
  sections?: { title: string; body: string; image?: string; fit?: "cover" | "contain" }[];
  /** Доп. доказательства (не свалка — 2–4 кадра) */
  gallery?: { src: string; alt: string; caption?: string; fit?: "cover" | "contain" }[];
  /** Итог — лид перед цифрами */
  outcomeLead?: string;
  highlights?: string[];
  ctaTitle?: string;
  ctaText?: string;
};

